import {rackIsAssigned,effectiveCustomerId} from './customers.js';
import {polygon,area,unionArea} from './geometry.js';
import {rackStats} from './racks.js';
export function report(doc,scope='all'){const floors=doc.floors.filter(f=>scope==='all'||f.id===scope).map(f=>{const shapes=f.shapes,sections=shapes.filter(o=>o.layer==='section').map(o=>({...o,stats:rackStats({...f,rackTypes:doc.rackTypes},o.id)})),footprint=unionArea(shapes.filter(o=>o.layer==='foundation')),sectionArea=unionArea(sections),reserved=unionArea(sections.filter(s=>s.rackPlacement===false)),used=sections.reduce((n,s)=>n+s.stats.used,0),assigned=sections.reduce((n,s)=>n+s.stats.assigned,0),pallets=f.racks.reduce((n,r)=>n+(doc.rackTypes.find(t=>t.id===r.typeId)?.pallets||0),0),assignedPallets=f.racks.filter(r=>rackIsAssigned(f,r)).reduce((n,r)=>n+(doc.rackTypes.find(t=>t.id===r.typeId)?.pallets||0),0);return {...f,sections,footprint,sectionArea,reserved,unsectioned:Math.max(0,footprint-sectionArea),used,assigned,unassigned:used-assigned,whitespace:Math.max(0,footprint-used-reserved),pallets,assignedPallets,unassignedPallets:pallets-assignedPallets,overlap:sections.reduce((n,s)=>n+area(polygon(s)),0)-sectionArea>1e-5};});const keys=['reserved','footprint','sectionArea','used','assigned','unassigned','whitespace','pallets','assignedPallets','unassignedPallets','unsectioned'];const total=Object.fromEntries(keys.map(k=>[k,floors.reduce((n,f)=>n+f[k],0)]));total.racks=floors.reduce((n,f)=>n+f.racks.length,0);total.sections=floors.reduce((n,f)=>n+f.sections.length,0);total.overlap=floors.some(f=>f.overlap);return {floors,total};}
const round=n=>Math.round(n*10000)/10000;
export function sheets(doc,scope='all'){const {floors}=report(doc,scope);return [{name:'Floors',headers:['Floor ID','Floor','Foundation m²','Section m²','Unsectioned m²','Rack m²','Assigned rack m²','Unassigned rack m²','Whitespace m²','Racks','Pallet positions','Assigned positions','Unassigned positions','Section overlap','Reserved non-storage m²'],rows:floors.map(f=>[f.id,f.label,...[f.footprint,f.sectionArea,f.unsectioned,f.used,f.assigned,f.unassigned,f.whitespace].map(round),f.racks.length,f.pallets,f.assignedPallets,f.unassignedPallets,f.overlap?'Yes':'No',round(f.reserved)])},{name:'Sections',headers:['Floor','Section ID','Section','Area m²','Rack m²','Assigned rack m²','Unassigned rack m²','Unracked m²','Racks','Assigned racks','Pallet positions','Rack placement','Reserved m²','Customer','Customer ID'],rows:floors.flatMap(f=>f.sections.map(s=>[f.label,s.id,s.name,...[s.stats.total,s.stats.used,s.stats.assigned,s.stats.unassigned,s.stats.free].map(round),s.stats.count,s.stats.assignedCount,s.stats.pallets,s.rackPlacement===false?'Disabled':'Enabled',round(s.stats.reserved),(doc.customers||[]).find(c=>c.id===s.customerId)?.name||'',(doc.customers||[]).find(c=>c.id===s.customerId)?.externalId||'']))},{name:'Rack Types',headers:['Type ID','Type','Length m','Width m','Height m','Footprint m²','Pallet positions'],rows:doc.rackTypes.map(t=>[t.id,t.name,t.length,t.width,t.height,round(t.length*t.width),t.pallets])},{name:'Racks',headers:['Floor','Section','Rack ID','Type','Length m','Width m','Height m','Footprint m²','Pallet positions','Status','Customer','Customer ID','Customer assignment'],rows:floors.flatMap(f=>f.racks.map(r=>{const t=doc.rackTypes.find(t=>t.id===r.typeId);return [f.label,f.shapes.find(s=>s.id===r.sectionId)?.name||'',r.id,t?.name||'',t?.length||0,t?.width||0,t?.height||0,round((t?.length||0)*(t?.width||0)),t?.pallets||0,rackIsAssigned(f,r)?'Assigned':'Unassigned',(doc.customers||[]).find(c=>c.id===effectiveCustomerId(f,r))?.name||'',(doc.customers||[]).find(c=>c.id===effectiveCustomerId(f,r))?.externalId||'',Object.hasOwn(r,'customerId')?(r.customerId?'Override':'Unassigned'):'Section default'];}))},{name:'Entrances',headers:['Floor','Entrance ID','Type','Width m','Status','Swing orientation °'],rows:floors.flatMap(f=>f.entrances.map(e=>[f.label,e.id,e.type==='swing'?'Swinging door':'Shutter',e.width,e.anchor?'Placed':'Not placed',e.type==='swing'?e.rotation:'']))},{name:'Customers',headers:['Internal ID','Name','Customer ID','Description'],rows:(doc.customers||[]).map(c=>[c.id,c.name,c.externalId||'',c.description||''])}];}
